  -H "Authorization: Bearer $KIMI_API_KEY" \
  -H "Content-Type: application/json" \
  -d '{
    "model": "kimi-k3",
    "messages": [\
      {"role": "user", "content": "Explain what a token bucket rate limiter does in one paragraph."}\
    ]
  }'
```
